package syssettings

import (
	_ "embed"
	"sort"
	"strings"
	"sync"
)

// zones.tsv is generated by ./gentz from Go's pinned tzdata; the router ships no zoneinfo.
//
//go:embed zones.tsv
var zonesTSV string

// UTC is OpenWrt's default zonename; its default timezone string is GMT0 (uci-export-system.txt).
const (
	UTC       = "UTC"
	utcPOSIX  = "GMT0"
	maxServer = 8
)

var zones = sync.OnceValue(func() map[string]string {
	out := map[string]string{UTC: utcPOSIX}
	for _, line := range strings.Split(strings.TrimSpace(zonesTSV), "\n") {
		name, tz, ok := strings.Cut(line, "\t")
		if ok {
			out[name] = tz
		}
	}
	return out
})

// POSIXTimezone returns the TZ string OpenWrt stores for an IANA zone name.
func POSIXTimezone(zonename string) (string, bool) {
	tz, ok := zones()[zonename]
	return tz, ok
}

// Zonenames lists every selectable zone, UTC first, then sorted.
func Zonenames() []string {
	names := make([]string, 0, len(zones()))
	for n := range zones() {
		if n != UTC {
			names = append(names, n)
		}
	}
	sort.Strings(names)
	return append([]string{UTC}, names...)
}
